"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/bulk-action-bar.css";
import { ArrowCounterClockwise, CheckCircle, WarningCircle, X } from "@phosphor-icons/react";
import type { HTMLAttributes, ReactNode } from "react";
import { cn } from "../../lib/cn";
import { IconButton } from "./icon-button";
import { Button } from "./button";
import { Spinner } from "./spinner";

export type BulkActionBarStatus = "ready" | "busy" | "complete" | "error";

export type BulkActionBarProps = HTMLAttributes<HTMLDivElement> & {
  count: number;
  noun?: string;
  actions?: ReactNode;
  onClear: () => void;
  busy?: boolean;
  status?: BulkActionBarStatus;
  message?: ReactNode;
  onUndo?: () => void;
  undoLabel?: string;
};

export function BulkActionBar({ count, noun = "row", actions, onClear, busy = false, status = "ready", message, onUndo, undoLabel = "Undo", className, ...props }: BulkActionBarProps) {
  const resolvedStatus = busy ? "busy" : status;
  if (count <= 0 && resolvedStatus === "ready") return null;
  const feedback = message ?? (resolvedStatus === "complete" ? count > 0 ? `${count} ${count === 1 ? noun : `${noun}s`} updated` : "Selection updated" : resolvedStatus === "error" ? "The action could not be completed" : "Updating selection");
  return (
    <div className={cn("whatiuse-bulk-action-bar", className)} data-status={resolvedStatus} role="region" aria-label="Bulk actions" aria-busy={resolvedStatus === "busy" || undefined} {...props}>
      {resolvedStatus === "ready" ? (
        <div className="whatiuse-bulk-action-bar__selection"><strong>{count}</strong><span>{noun}{count === 1 ? "" : "s"} selected</span></div>
      ) : (
        <div className="whatiuse-bulk-action-bar__feedback">
          {resolvedStatus === "busy" ? <Spinner size="small" label="Updating selection" /> : resolvedStatus === "complete" ? <CheckCircle aria-hidden="true" weight="fill" /> : <WarningCircle aria-hidden="true" />}
          <span>{feedback}</span>
        </div>
      )}
      <div className="whatiuse-bulk-action-bar__actions">{resolvedStatus === "ready" ? actions : resolvedStatus === "complete" && onUndo ? <Button size="small" variant="quiet" leadingIcon={<ArrowCounterClockwise />} onClick={onUndo}>{undoLabel}</Button> : null}</div>
      <IconButton size="small" variant="ghost" aria-label="Clear selection" onClick={onClear}><X aria-hidden="true" /></IconButton>
      <span className="whatiuse-sr-only" aria-live="polite">{resolvedStatus === "ready" ? `${count} ${noun}${count === 1 ? "" : "s"} selected` : feedback}</span>
    </div>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-bulk-action-bar {
  display: flex;
  min-height: 46px;
  align-items: center;
  gap: 10px;
  padding: 6px 7px 6px 12px;
  border-radius: 9px;
  background: var(--whatiuse-inverse);
  color: var(--whatiuse-on-inverse);
  box-shadow: 0 12px 32px rgb(0 0 0 / .18);
  opacity: 1;
  transform: translateY(0);
  transition: opacity 160ms var(--whatiuse-ease-out), transform 180ms var(--whatiuse-ease-out);
}

@starting-style {
.whatiuse-bulk-action-bar { opacity: 0; transform: translateY(8px); }
}

.whatiuse-bulk-action-bar__selection {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  white-space: nowrap;
}

.whatiuse-bulk-action-bar__selection strong { font-size: var(--whatiuse-type-ui); font-weight: 650; font-variant-numeric: tabular-nums; }

.whatiuse-bulk-action-bar__selection span { color: color-mix(in oklch, var(--whatiuse-on-inverse) 72%, transparent); font-size: var(--whatiuse-type-label); }

.whatiuse-bulk-action-bar__actions {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
}

.whatiuse-bulk-action-bar .whatiuse-button,
.whatiuse-bulk-action-bar .whatiuse-icon-button { color: var(--whatiuse-on-inverse); }

@media (prefers-reduced-motion: reduce) {
.whatiuse-bulk-action-bar { transform: none; transition: opacity 120ms var(--whatiuse-ease-out); }
}

.whatiuse-bulk-action-bar {
    min-height: 44px;
    gap: 8px;
    padding: 6px 7px 6px 11px;
    border: 1px solid color-mix(in oklch, var(--whatiuse-control-border) 72%, transparent);
    border-radius: 10px;
    background: var(--whatiuse-bg-flyout);
    color: var(--whatiuse-fg-default);
    box-shadow: 0 12px 32px -20px rgb(17 17 19 / .32), var(--whatiuse-shadow-control);
    transform: translateY(0);
  }

.whatiuse-bulk-action-bar__selection span { color: var(--whatiuse-fg-subtle); }

.whatiuse-bulk-action-bar .whatiuse-button,
.whatiuse-bulk-action-bar .whatiuse-icon-button { color: var(--whatiuse-fg-muted); }

@starting-style {
.whatiuse-bulk-action-bar { opacity: 0; transform: translateY(2px); }
}

@media (prefers-reduced-motion: reduce) {
.whatiuse-bulk-action-bar { transform: none; }
}

.whatiuse-bulk-action-bar__feedback { display: inline-flex; min-width: 0; align-items: center; gap: 7px; color: var(--whatiuse-fg-muted); font-size: var(--whatiuse-type-label); }

.whatiuse-bulk-action-bar__feedback svg { flex: 0 0 auto; }

.whatiuse-bulk-action-bar[data-status="error"] .whatiuse-bulk-action-bar__feedback { color: var(--whatiuse-fg-danger); }
}
